<?php
/*
 * Contact form handler for markopoulos-oliveoil.gr
 * GENERATED by build.py from src/static-templates/contact.php.
 * Change the email address in site.json, not here.
 */

$TO     = 'info@markopoulos-oliveoil.gr';
$FROM   = 'noreply@markopoulos-oliveoil.gr';
$SITE   = 'Ελαιοτριβείο Μαρκόπουλος';
$THANKS = array('el' => '/efharistoume.html', 'en' => '/en/thank-you.html');
$BACK   = array('el' => '/epikoinonia.html',   'en' => '/en/contact.html');

function go($to) { header('Location: ' . $to, true, 303); exit; }

function field($key, $max) {
    $v = isset($_POST[$key]) ? (string)$_POST[$key] : '';
    $v = trim(str_replace(array("\r", "\0"), '', $v));
    return function_exists('mb_substr') ? mb_substr($v, 0, $max, 'UTF-8') : substr($v, 0, $max * 2);
}

if ($_SERVER['REQUEST_METHOD'] !== 'POST') { go('/'); }

$lang = (isset($_POST['lang']) && $_POST['lang'] === 'en') ? 'en' : 'el';
$back = $BACK[$lang];

$name     = field('name', 120);
$email    = field('email', 160);
$phone    = field('phone', 40);
$quantity = field('quantity', 80);
$message  = field('message', 5000);
$honeypot = field('website', 200);
$started  = isset($_POST['t']) ? (int)$_POST['t'] : 0;
$consent  = !empty($_POST['consent']);

// Spam: the hidden "website" field is filled in, or the form was sent in under 3 seconds.
if ($honeypot !== '' || ($started > 0 && time() - $started < 3)) { go($THANKS[$lang]); }

if ($name === '' || $message === '' || ($email === '' && $phone === '') || !$consent) { go($back . '?error=missing#form'); }
if ($email !== '' && !filter_var($email, FILTER_VALIDATE_EMAIL)) { go($back . '?error=email#form'); }
if ($TO === '') { go($back . '?error=send#form'); }

$oneLine = function ($s) { return str_replace("\n", ' ', $s); };

$subject = 'Μήνυμα από την ιστοσελίδα: ' . $oneLine($name);
$body  = "Νέο μήνυμα από τη φόρμα επικοινωνίας ({$lang})\n";
$body .= "------------------------------------------\n";
$body .= "Όνομα:     " . $oneLine($name) . "\n";
$body .= "Τηλέφωνο:  " . ($phone !== '' ? $oneLine($phone) : '-') . "\n";
$body .= "Email:     " . ($email !== '' ? $email : '-') . "\n";
$body .= "Ποσότητα:  " . ($quantity !== '' ? $oneLine($quantity) : '-') . "\n";
$body .= "------------------------------------------\n\n";
$body .= $message . "\n\n";
$body .= "Στάλθηκε: " . date('d/m/Y H:i') . "\n";

$encName = '=?UTF-8?B?' . base64_encode($SITE) . '?=';
$headers  = "From: {$encName} <{$FROM}>\r\n";
if ($email !== '') { $headers .= "Reply-To: {$email}\r\n"; }
$headers .= "MIME-Version: 1.0\r\n";
$headers .= "Content-Type: text/plain; charset=UTF-8\r\n";
$headers .= "Content-Transfer-Encoding: 8bit\r\n";

$ok = @mail($TO, '=?UTF-8?B?' . base64_encode($subject) . '?=', $body, $headers, '-f' . $FROM);

go($ok ? $THANKS[$lang] : $back . '?error=send#form');
